import{_ as a,c as n,o as i,ag as t}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Testing, review and maintainable design","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/quality.md","filePath":"engineering/quality.md"}'),r={name:"engineering/quality.md"};function o(s,e,_,c,d,l){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="testing-review-and-maintainable-design" tabindex="-1">Testing, review and maintainable design <a class="header-anchor" href="#testing-review-and-maintainable-design" aria-label="Permalink to “Testing, review and maintainable design”">​</a></h1><p><strong>Prerequisites:</strong> A stated input/output contract and an owned small project. Review baseline: 2026-10-27. All learner practice remains outstanding.</p><h2 id="observe-a-real-defect" tabindex="-1"><span class="hub-section-number">1 </span>Observe a real defect <a class="header-anchor" href="#observe-a-real-defect" aria-label="Permalink to “1 Observe a real defect”">​</a></h2><p><a href="./../senior_growth/Testing/TDD_-_pros_and_cons(red%2C_green%2C_refactor).html">Red/green/refactor fixture</a> → <a href="./../senior_growth/Testing/FIRST_principles_-_how_a_good_unit_test_looks_like.html">Fixture and cleanup discipline</a> → <a href="./../senior_growth/Testing/What_is_code_coverage%2C_how_do_you_measure_it%2C_what_kinds_do_you_know_What_do_you_think_is_the_ideal_amount.html">Coverage counterexample</a>. Red must fail for the intended behavioral reason, not a missing tool. Coverage counts execution; a weak assertion can cover a defect.</p><h2 id="choose-evidence-by-boundary" tabindex="-1"><span class="hub-section-number">2 </span>Choose evidence by boundary <a class="header-anchor" href="#choose-evidence-by-boundary" aria-label="Permalink to “2 Choose evidence by boundary”">​</a></h2><p><a href="./../senior_growth/Testing/What_is_snapshot_testing_When_should_we_avoid_using_it.html">Serialization versus pixels</a>; <a href="./../frontend/verification.html">frontend behavior checks</a>; <a href="./../node-js/module-04-testing.html">real Node/database tests</a>. Mocked adapters cannot establish SQL isolation or native focus/announcement behavior.</p><h2 id="enforce-a-focused-policy" tabindex="-1"><span class="hub-section-number">3 </span>Enforce a focused policy <a class="header-anchor" href="#enforce-a-focused-policy" aria-label="Permalink to “3 Enforce a focused policy”">​</a></h2><p><a href="./../senior_growth/Clean_code_and_Code_Quality/What_is_code_standard_What_code_standard_is_on_your_current_project_Should_we_always_work_by_code_standard_Have_you_used_linters_and_do_you_have_any_experience_in_configuring_them.html">Minimal executable standard</a> → <a href="./../senior_growth/Clean_code_and_Code_Quality/What_does_quality_gate_mean_for_you_–_an_ideal_set_up_of_quality_gates.html">Gate limits</a> → <a href="./../senior_growth/Clean_code_and_Code_Quality/Why_code_review_is_important_and_how_does_it_work_on_your_project%2C_what_is_your_own_work_flow_for_it.html">Contract-based review</a>. Required compiler/lint/test/build checks need independent failure evidence; hooks are bypassable and scanners are incomplete.</p><h2 id="use-a-pattern-only-for-a-real-variation" tabindex="-1"><span class="hub-section-number">4 </span>Use a pattern only for a real variation <a class="header-anchor" href="#use-a-pattern-only-for-a-real-variation" aria-label="Permalink to “4 Use a pattern only for a real variation”">​</a></h2><p><a href="./../senior_growth/Coding_principles_patterns_conventions/Can_you_decipher_SOLID_acronym_What_is_&quot;L&quot;.html">Behavioral substitution</a> → <a href="./../senior_growth/Coding_principles_patterns_conventions/Please_describe_Strategy_design_pattern._What_are_the_valid_use_cases_for_it.html">Injected strategy</a> → <a href="./../senior_growth/Coding_principles_patterns_conventions/What_design_patterns_do_you_use_on_daily_basis_in_JS%2C_why_are_they_useful.html">Owned notifications/history</a>. Preserve effects, identity and error contracts; avoid speculative abstraction. <a href="./../senior_growth/EngX_Quality/How_would_you_approach_significant_refactoring.html">Refactor seam</a> supplies characterization and a bounded debt decision.</p><h2 id="practice-and-verification" tabindex="-1"><span class="hub-section-number">5 </span>Practice and verification <a class="header-anchor" href="#practice-and-verification" aria-label="Permalink to “5 Practice and verification”">​</a></h2><p>Use <a href="./../practice/engineering/">the shared increments</a> and linked focused requirements. <a href="./../workbench/engineering/">Workbench</a> contains canonical references; <a href="./../review/verification.html">verification</a> distinguishes current checks, preserved historical evidence and unperformed integrations.</p>',12)])])}const p=a(r,[["render",o]]);export{u as __pageData,p as default};
